#include "ufbx.h"
#include <stdio.h>
#include <stdlib.h>
#include <math.h>
static void str(ufbx_string s){putchar('"');for(size_t i=0;i<s.length;i++){char c=s.data[i];if(c=='"'||c=='\\')putchar('\\');if((unsigned char)c>=32)putchar(c);}putchar('"');}
static void vec(ufbx_vec3 v){printf("[%.9g,%.9g,%.9g]",v.x,v.y,v.z);}
static void mat(ufbx_matrix m){printf("[");for(int c=0;c<4;c++){if(c)printf(",");printf("%.9g,%.9g,%.9g",m.cols[c].x,m.cols[c].y,m.cols[c].z);}printf("]");}
static void trs(ufbx_transform t){printf("[%.9g,%.9g,%.9g,%.9g,%.9g,%.9g,%.9g,%.9g,%.9g,%.9g]",t.translation.x,t.translation.y,t.translation.z,t.rotation.x,t.rotation.y,t.rotation.z,t.rotation.w,t.scale.x,t.scale.y,t.scale.z);}
int main(int argc,char**argv){if(argc!=2){fprintf(stderr,"Usage: dump input.fbx > output.json\n");return 64;}ufbx_load_opts opt={0};ufbx_error err;ufbx_scene*s=ufbx_load_file(argv[1],&opt,&err);if(!s){fprintf(stderr,"load failed %s\n",err.description.data);return 1;}printf("{\"unitMeters\":%.9g,\"nodes\":[",s->settings.unit_meters);
for(size_t i=0;i<s->nodes.count;i++){ufbx_node*n=s->nodes.data[i];if(i)putchar(',');printf("{\"name\":");str(n->name);printf(",\"parent\":%d,\"trs\":",n->parent?(int)n->parent->typed_id:-1);trs(n->local_transform);printf(",\"mesh\":%d}",n->mesh?(int)n->mesh->typed_id:-1);}
printf("],\"meshes\":[");for(size_t mi=0;mi<s->meshes.count;mi++){ufbx_mesh*m=s->meshes.data[mi];if(mi)putchar(',');printf("{\"vertices\":[");for(size_t i=0;i<m->vertices.count;i++){if(i)putchar(',');vec(m->vertices.data[i]);}printf("],\"indices\":[");for(size_t i=0;i<m->num_indices;i++){if(i)putchar(',');printf("%u",m->vertex_indices.data[i]);}printf("],\"normals\":[");for(size_t i=0;i<m->num_indices;i++){if(i)putchar(',');vec(ufbx_get_vertex_vec3(&m->vertex_normal,i));}printf("],\"uv\":[");for(size_t i=0;i<m->num_indices;i++){if(i)putchar(',');ufbx_vec2 v=ufbx_get_vertex_vec2(&m->vertex_uv,i);printf("[%.9g,%.9g]",v.x,v.y);}printf("],\"faces\":[");for(size_t i=0;i<m->faces.count;i++){if(i)putchar(',');printf("[%u,%u]",m->faces.data[i].index_begin,m->faces.data[i].num_indices);}printf("],\"triangles\":%zu,\"skins\":[",m->num_triangles);
for(size_t di=0;di<m->skin_deformers.count;di++){ufbx_skin_deformer*d=m->skin_deformers.data[di];if(di)putchar(',');printf("{\"clusters\":[");for(size_t i=0;i<d->clusters.count;i++){ufbx_skin_cluster*c=d->clusters.data[i];if(i)putchar(',');printf("{\"node\":%u,\"inverse\":",c->bone_node->typed_id);mat(c->geometry_to_bone);printf(",\"bind\":");mat(c->bind_to_world);printf("}");}printf("],\"weights\":[");for(size_t vi=0;vi<d->vertices.count;vi++){if(vi)putchar(',');putchar('[');ufbx_skin_vertex v=d->vertices.data[vi];for(size_t j=0;j<v.num_weights;j++){if(j)putchar(',');ufbx_skin_weight w=d->weights.data[v.weight_begin+j];printf("[%u,%.9g]",w.cluster_index,w.weight);}putchar(']');}printf("]}");}printf("]}");}
printf("],\"clips\":[");for(size_t ai=0;ai<s->anim_stacks.count;ai++){ufbx_anim_stack*a=s->anim_stacks.data[ai];if(ai)putchar(',');printf("{\"name\":");str(a->name);printf(",\"start\":%.9g,\"end\":%.9g,\"frames\":[",a->time_begin,a->time_end);int count=(int)ceil((a->time_end-a->time_begin)*60.0);for(int f=0;f<=count;f++){double t=fmin(a->time_end,a->time_begin+f/60.0);ufbx_evaluate_opts eo={0};ufbx_scene*e=ufbx_evaluate_scene(s,a->anim,t,&eo,&err);if(!e)return 2;if(f)putchar(',');printf("{\"t\":%.9g,\"local\":[",t-a->time_begin);for(size_t i=0;i<e->nodes.count;i++){if(i)putchar(',');trs(e->nodes.data[i]->local_transform);}printf("],\"world\":[");for(size_t i=0;i<e->nodes.count;i++){if(i)putchar(',');vec(e->nodes.data[i]->node_to_world.cols[3]);}printf("]}");ufbx_free_scene(e);}printf("]}");}printf("]}\n");ufbx_free_scene(s);return 0;}
